{
  "name": "PI E-709压电定位控制器",
  "name_en": "PI E-709 Piezo Positioning Controller",
  "manufacturer": "Physik Instrumente (PI)",
  "description": "用于控制双通道或XY压电定位平台的运动控制器，可执行绝对/相对移动、伺服闭环控制、位置读取、到位判断和参考初始化，常用于显微成像中的纳米级定位与扫描。",
  "description_en": "A motion controller for dual-channel or XY piezo positioning stages. It supports absolute/relative moves, closed-loop servo control, position readback, on-target checks, and reference initialization, commonly used for nanoscale positioning and scanning in microscopy.",
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭与压电控制器的通信连接。",
      "description_en": "Close the communication connection to the piezo controller."
    },
    {
      "action_name": "auto-SetServo",
      "description": "设置伺服闭环控制状态。",
      "description_en": "Set the closed-loop servo control state."
    },
    {
      "action_name": "auto-ReInit",
      "description": "重新初始化控制器，并可选择执行参考定位流程。",
      "description_en": "Reinitialize the controller and optionally run the reference-finding procedure."
    },
    {
      "action_name": "auto-MoveTo",
      "description": "将指定通道移动到绝对目标位置。",
      "description_en": "Move the specified channel to an absolute target position."
    },
    {
      "action_name": "auto-MoveRel",
      "description": "使指定通道相对当前位置移动指定增量。",
      "description_en": "Move the specified channel by a relative increment from its current position."
    },
    {
      "action_name": "auto-OnTarget",
      "description": "查询设备是否已到达目标位置。",
      "description_en": "Query whether the device has reached its target position."
    },
    {
      "action_name": "auto-GetPos",
      "description": "读取指定通道的当前位置。",
      "description_en": "Read the current position of the specified channel."
    },
    {
      "action_name": "auto-GetPosXY",
      "description": "读取XY两个通道的当前位置。",
      "description_en": "Read the current positions of the X and Y channels."
    },
    {
      "action_name": "auto-GetTargetPos",
      "description": "读取指定通道的目标位置。",
      "description_en": "Read the target position of the specified channel."
    },
    {
      "action_name": "auto-MoveInDir",
      "description": "按给定方向分量驱动XY轴运动。",
      "description_en": "Drive the XY axes in the specified direction components."
    },
    {
      "action_name": "auto-StopMove",
      "description": "停止当前运动。",
      "description_en": "Stop the current motion."
    },
    {
      "action_name": "auto-GetControlReady",
      "description": "查询控制器是否已准备好接收控制命令。",
      "description_en": "Query whether the controller is ready to accept control commands."
    },
    {
      "action_name": "auto-GetChannelObject",
      "description": "查询通道对象标识或配置。",
      "description_en": "Query the channel object identifier or configuration."
    },
    {
      "action_name": "auto-GetChannelPhase",
      "description": "查询通道相位信息。",
      "description_en": "Query channel phase information."
    },
    {
      "action_name": "auto-GetMin",
      "description": "查询指定通道的最小允许位置。",
      "description_en": "Query the minimum allowed position for the specified channel."
    },
    {
      "action_name": "auto-GetMax",
      "description": "查询指定通道的最大允许位置。",
      "description_en": "Query the maximum allowed position for the specified channel."
    },
    {
      "action_name": "auto-GetFirmwareVersion",
      "description": "查询控制器固件版本。",
      "description_en": "Query the controller firmware version."
    }
  ],
  "tag_hints": [
    "piezo nanopositioning",
    "XY stage control",
    "closed-loop servo",
    "microscopy positioning",
    "serial motion controller",
    "reference finding",
    "nanometer motion"
  ]
}

